// Select videos that:
// 0. Are about the active event (title mentions its city/number or fighters).
// 1. Have never been analysed.
// 2. Previously failed and still have retry attempts remaining.
// 3. Were explicitly marked RETRY and still have attempts remaining.
// 4. Were left stuck in PROCESSING by an interrupted workflow and are stale.
//
// analysis_attempt_count should be incremented only by
// the node named "Mark Analysis Processing".

const MAX_ANALYSIS_ATTEMPTS = 3;

// A PROCESSING record older than this is considered abandoned.
const STALE_PROCESSING_HOURS = 1;

const nowMs = Date.now();
const staleThresholdMs =
  STALE_PROCESSING_HOURS * 60 * 60 * 1000;

function ufcText(value) {
 return String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' ');
}
function ufcHas(text, phrase) { return phrase && (' '+text+' ').includes(' '+phrase+' '); }
function ufcEventSignals(event, title) {
 const name=ufcText(event.event_name);
 const split=String(event.event_name || '').split(':');
 const prefix=ufcText(split[0]);
 const number=(prefix.match(/\bufc\s+(\d{2,4})\b/) || [])[1];
 const pair=String(split.slice(1).join(':') || '').split(/\s+v(?:s)?\.?\s+/i);
 const surname=value=>ufcText(value).split(' ').filter(word=>!['jr','sr','ii','iii','iv'].includes(word)).slice(-1)[0] || '';
 const a=surname(pair[0]), b=surname(pair[1]);
 const matchup=pair.length===2 && a.length>=3 && b.length>=3 && ufcHas(title,a) && ufcHas(title,b);
 const numbered=Boolean(number && new RegExp('\\bufc\\s+'+number+'\\b').test(title));
 const venue=prefix.replace(/\bufc\b/g,' ').replace(/\bfight\s+night\b/g,' ').replace(/\b\d+\b/g,' ').trim().replace(/\s+/g,' ');
 const location=venue.length>=3 && ufcHas(title,venue);
 return {event, score: matchup || numbered ? 10 : location ? 4 : 0, reason: matchup ? 'main-event surnames' : numbered ? 'UFC event number' : location ? 'event location' : ''};
}
function classifyUfcVideo(title, active, events) {
 const text=ufcText(title);
 const pool=[...new Map([...(events||[]),active].filter(event=>event?.event_key&&event.event_name).map(event=>[event.event_key,event])).values()];
 const matches=pool.map(event=>ufcEventSignals(event,text)).filter(match=>match.score>0);
 const strong=matches.filter(match=>match.score===10);
 const candidates=strong.length ? strong : matches;
 if(candidates.length!==1) return {event_match_status:candidates.length>1?'AMBIGUOUS':'UNCONFIRMED',event_match_reason:candidates.length>1?'Title identifies more than one known UFC event':'Title does not clearly identify a known UFC event',matched_event_key:'',event_match_version:'ufc-event-match-v2'};
 const match=candidates[0];
 return {event_match_status:match.event.event_key===active.event_key?'MATCHED':'OTHER_EVENT',event_match_reason:'Matched '+match.event.event_name+' by '+match.reason,matched_event_key:match.event.event_key,event_match_version:'ufc-event-match-v2'};
}
const activeEvent=$('One Active Event Only').first().json;
const knownEvents=$('Get UFC Events For Matching').all().map(item=>item.json);
let request={}; try {request=$('When Executed by Another Workflow').first().json;} catch {}
const target=request.manual_retry===true ? String(request.target_video_id || '') : '';
const selected = $input.all().filter((item) => {
  const row = item.json;

  if (!row.video_id || (target && row.video_id !== target) || classifyUfcVideo(row.video_title,activeEvent,knownEvents).event_match_status !== 'MATCHED') {
    return false;
  }

  const status = String(
    row.analysis_status || ''
  )
    .trim()
    .toUpperCase();

  const attempts = Number(
    row.analysis_attempt_count || 0
  );

  const validAttempts =
    Number.isFinite(attempts) && attempts >= 0
      ? attempts
      : 0;

  const hasAttemptsRemaining =
    validAttempts < MAX_ANALYSIS_ATTEMPTS || Boolean(target);

  /*
  Prefer last_attempt_at because it records when analysis began.
  Fall back to updatedAt for older rows.
  */
  const processingTimestamp =
    row.last_attempt_at ||
    row.updatedAt ||
    null;

  const processingTimeMs =
    processingTimestamp
      ? Date.parse(processingTimestamp)
      : NaN;

  const processingIsStale =
    status === 'PROCESSING' &&
    (
      !Number.isFinite(processingTimeMs) ||
      nowMs - processingTimeMs >= staleThresholdMs
    );

  const neverAnalysed =
    status === '';

  const retryableFailure =
    status === 'FAILED' &&
    hasAttemptsRemaining;

  const markedForRetry =
    status === 'RETRY' &&
    hasAttemptsRemaining;

  // Flagged by svc.apply_card_changes after the fight card changed; re-analysed whatever its attempt count.
  const cardChanged =
    status === 'CARD_CHANGED';

  const retryableStaleProcessing =
    processingIsStale &&
    hasAttemptsRemaining;

  return (
    (target && status === 'RETRY_REQUESTED') || neverAnalysed || cardChanged ||
    retryableFailure ||
    markedForRetry ||
    retryableStaleProcessing
  );
});

return selected.length ? selected : [{json:{__no_analysis_work:true}}];

// Reassemble chunked transcript rows into one complete transcript per video.

const rows = $input.all().map((item) => item.json);
const grouped = new Map();

for (const row of rows) {
  const videoId = String(row.video_id || '').trim();
  const transcriptText = String(row.transcript_text || '').trim();

  if (!videoId || !transcriptText) {
    continue;
  }

  if (!grouped.has(videoId)) {
    grouped.set(videoId, {
      video_id: videoId,
      channel_name: row.channel_name || '',
      video_title: row.video_title || '',
      video_url: row.video_url || '',
      published_at: row.published_at || '',
      parts: [],
    });
  }

  grouped.get(videoId).parts.push({
    part_number: Number(row.part_number || 1),
    text: transcriptText,
  });
}

const output = [];

for (const video of grouped.values()) {
  video.parts.sort((a, b) => a.part_number - b.part_number);

  const fullTranscript = video.parts
    .map((part) => part.text)
    .join('\n\n');

  output.push({
    json: {
      video_id: video.video_id,
      channel_name: video.channel_name,
      video_title: video.video_title,
      video_url: video.video_url,
      published_at: video.published_at,
      transcript_part_count: video.parts.length,
      transcript_text: fullTranscript,
      input_characters: fullTranscript.length,
    },
  });
}

return output;

const fights = $input.all()
  .map((item) => item.json)
  .filter((row) => row.fighter_a && row.fighter_b)
  .sort(
    (a, b) =>
      Number(a.fight_order || 999) -
      Number(b.fight_order || 999)
  );

const missingBoutIds = fights
  .filter((fight) => !String(fight.bout_id || '').trim())
  .map((fight) => fight.fight_order);

if (missingBoutIds.length > 0) {
  throw new Error(
    `Fight Card is missing bout_id for fight ${missingBoutIds.join(', ')}. ` +
    'Run svc.sync_bout_ids before analysis.'
  );
}

const lines = fights.map((fight) => {
  const aliasesA = String(fight.fighter_a_aliases || '').trim();
  const aliasesB = String(fight.fighter_b_aliases || '').trim();

  return [
    `Fight ${fight.fight_order}:`,
    `- Fighter A: ${fight.fighter_a}`,
    aliasesA ? `- Fighter A aliases: ${aliasesA}` : null,
    `- Fighter B: ${fight.fighter_b}`,
    aliasesB ? `- Fighter B aliases: ${aliasesB}` : null,
    fight.weight_class ? `- Weight class: ${fight.weight_class}` : null,
    `- Scheduled rounds: ${fight.scheduled_rounds || 3}`,
    `- Bout type: ${fight.bout_type || ''}`,
  ]
    .filter(Boolean)
    .join('\n');
});

return [
  {
    json: {
      fight_card_context: lines.join('\n\n'),
      fight_count: fights.length,
      fight_bout_ids: Object.fromEntries(
        fights.map((fight) => [
          Number(fight.fight_order),
          String(fight.bout_id).trim(),
        ])
      ),
    },
  },
];

const inputItems = $input.all();

if (inputItems.length !== 1) {
  throw new Error(
    `Parse OpenRouter Extraction expected exactly 1 input item, received ${inputItems.length}`
  );
}

const response = inputItems[0].json;

const source =
  $('Loop Over Videos').item.json;

/*
Handle OpenRouter API-level errors.
*/
if (response?.error) {
  throw new Error(
    `OpenRouter error: ${JSON.stringify(response.error).slice(0, 3000)}`
  );
}

/*
A normal Chat Completions response should contain at least one choice.
*/
const choice =
  response?.choices?.[0];

if (!choice) {
  throw new Error(
    `OpenRouter returned no choices. Response: ${JSON.stringify(response).slice(0, 3000)}`
  );
}

const finishReason =
  String(choice.finish_reason || '');

const nativeFinishReason =
  String(choice.native_finish_reason || '');

const reasoningTokens =
  response?.usage?.completion_tokens_details?.reasoning_tokens ??
  response?.usage?.reasoning_tokens ??
  null;

/*
Reject truncated/incomplete model responses.
*/
if (finishReason !== 'stop') {
  throw new Error(
    `Extraction did not finish normally. ` +
    `finish_reason=${finishReason || 'missing'}, ` +
    `native_finish_reason=${nativeFinishReason || 'missing'}, ` +
    `completion_tokens=${response?.usage?.completion_tokens ?? 'unknown'}, ` +
    `reasoning_tokens=${reasoningTokens ?? 'unknown'}`
  );
}

const content =
  choice?.message?.content;

if (
  content == null ||
  String(content).trim() === ''
) {
  throw new Error(
    `OpenRouter returned empty content. ` +
    `finish_reason=${finishReason}, ` +
    `reasoning_tokens=${reasoningTokens ?? 'unknown'}`
  );
}

/*
Parse the model response.
*/
let extracted;

if (
  typeof content === 'object' &&
  content !== null
) {
  extracted = content;
} else {
  const cleaned = String(content)
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');

  try {
    extracted =
      JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      `Could not parse OpenRouter JSON: ${error.message}. ` +
      `Response begins: ${cleaned.slice(0, 2000)}`
    );
  }
}

/*
Top-level result must be a JSON object.
*/
if (
  !extracted ||
  typeof extracted !== 'object' ||
  Array.isArray(extracted)
) {
  throw new Error(
    'Parsed extraction is not a JSON object'
  );
}

/*
The ONLY required top-level extraction field is fights.

Parlays are no longer part of this workflow.
*/
if (!Array.isArray(extracted.fights)) {
  throw new Error(
    'Parsed extraction does not contain a fights array'
  );
}

/*
Normalize each fight.

No props is valid, so missing props becomes [].
No winner pick is valid, so missing winner_pick becomes null.
*/
const fights =
  extracted.fights.map(
    (fight, index) => {
      if (
        !fight ||
        typeof fight !== 'object' ||
        Array.isArray(fight)
      ) {
        throw new Error(
          `Fight at array index ${index} is not a valid object`
        );
      }

      const normalizedFight = {
        ...fight,
      };

      if (
        normalizedFight.props === undefined ||
        normalizedFight.props === null
      ) {
        normalizedFight.props = [];
      }

      if (
        !Array.isArray(normalizedFight.props)
      ) {
        throw new Error(
          `Fight ${
            normalizedFight.fight_order ?? index + 1
          } contains an invalid props value`
        );
      }

      if (
        normalizedFight.winner_pick === undefined
      ) {
        normalizedFight.winner_pick = null;
      }

      return normalizedFight;
    }
  );

/*
Return source metadata plus the normalized extraction.

No parlays field is created or expected anywhere here.
*/
return [
  {
    json: {
      ...source,

      output: {
        fights,
      },

      fights,

      openrouter_model:
        response.model ?? null,

      openrouter_provider:
        response.provider ?? null,

      openrouter_finish_reason:
        finishReason,

      openrouter_native_finish_reason:
        nativeFinishReason || null,

      openrouter_prompt_tokens:
        response?.usage?.prompt_tokens ?? null,

      openrouter_completion_tokens:
        response?.usage?.completion_tokens ?? null,

      openrouter_reasoning_tokens:
        reasoningTokens,

      openrouter_total_tokens:
        response?.usage?.total_tokens ?? null,

      openrouter_cost:
        response?.usage?.cost ?? null,

      openrouter_metadata:
        response?.openrouter_metadata ?? null,
    },
  },
];

const source = $json;

const extracted =
  source.output || source;

const rawFights =
  Array.isArray(extracted.fights)
    ? extracted.fights
    : [];

const validationErrors = [];
const seenFightOrders = new Set();

function normalizeFight(rawFight) {
  const fight = {
    ...rawFight,
  };

  let fighterA =
    String(fight.fighter_a || '').trim();

  let fighterB =
    String(fight.fighter_b || '').trim();

  if (
    (!fighterA || !fighterB) &&
    fight.matchup
  ) {
    const matchup =
      String(fight.matchup).trim();

    const parts =
      matchup.split(/\s+vs\.?\s+/i);

    if (parts.length === 2) {
      fighterA =
        fighterA || parts[0].trim();

      fighterB =
        fighterB || parts[1].trim();
    }
  }

  let winnerPick =
    fight.winner_pick ?? null;

  if (
    winnerPick &&
    typeof winnerPick === 'object'
  ) {
    winnerPick = {
      ...winnerPick,

      odds_mentioned:
        winnerPick.odds_mentioned ??
        winnerPick.odds ??
        null,
    };

    delete winnerPick.odds;
  }

  const props =
    Array.isArray(fight.props)
      ? fight.props.map((rawProp) => {
          const prop = {
            ...rawProp,

            odds_mentioned:
              rawProp.odds_mentioned ??
              rawProp.odds ??
              null,

            round_range:
              rawProp.round_range ??
              null,
          };

          delete prop.odds;

          return prop;
        })
      : [];

  return {
    ...fight,

    fighter_a:
      fighterA,

    fighter_b:
      fighterB,

    winner_pick:
      winnerPick,

    props,
  };
}

const fights =
  rawFights.map(normalizeFight);

for (const fight of fights) {
  const fightOrder =
    Number(fight.fight_order);

  if (
    !Number.isInteger(fightOrder) ||
    fightOrder < 1
  ) {
    validationErrors.push(
      `Invalid fight_order: ${fight.fight_order}`
    );

    continue;
  }

  if (
    Number.isInteger(Number(source.fight_count)) &&
    fightOrder > Number(source.fight_count)
  ) {
    validationErrors.push(
      `fight_order ${fightOrder} exceeds fight_count ${source.fight_count}`
    );
  }

  if (
    seenFightOrders.has(fightOrder)
  ) {
    validationErrors.push(
      `Duplicate fight_order: ${fightOrder}`
    );
  }

  seenFightOrders.add(
    fightOrder
  );

  if (!fight.fighter_a) {
    validationErrors.push(
      `Fight ${fightOrder} is missing fighter_a`
    );
  }

  if (!fight.fighter_b) {
    validationErrors.push(
      `Fight ${fightOrder} is missing fighter_b`
    );
  }

  if (!Array.isArray(fight.props)) {
    validationErrors.push(
      `Fight ${fightOrder} does not contain a props array`
    );
  }

  if (
    fight.winner_pick !== null &&
    fight.winner_pick !== undefined &&
    typeof fight.winner_pick !== 'object'
  ) {
    validationErrors.push(
      `Fight ${fightOrder} has an invalid winner_pick`
    );
  }
}

fights.sort((a, b) => {
  return (
    Number(a.fight_order ?? 999) -
    Number(b.fight_order ?? 999)
  );
});

const winnerPickCount =
  fights.filter((fight) => {
    return Boolean(
      fight.winner_pick &&
      typeof fight.winner_pick === 'object' &&
      String(
        fight.winner_pick.picked_fighter || ''
      ).trim()
    );
  }).length;

if (winnerPickCount === 0) {
  validationErrors.push(
    'Extraction contained zero winner picks.'
  );
}

if (
  validationErrors.length > 0
) {
  throw new Error(
    `Extraction validation failed: ${validationErrors.join(' | ')}`
  );
}

return {
  json: {
    ...source,

    output: {
      fights,
    },

    fights,

    extracted_fight_count:
      fights.length,

    extracted_winner_pick_count:
      winnerPickCount,

    validation_status:
      'PASSED',

    validation_errors:
      [],
  },
};

const source = $input.first().json;

const rows = Array.isArray(source.pick_rows)
  ? source.pick_rows
  : [];

if (rows.length === 0) {
  return [
    {
      json: {
        has_pick_rows: false,
        video_id: source.video_id,
        event_key: source.event_key,
        spreadsheet_id: source.spreadsheet_id,
        pick_row_count: 0
      },
      pairedItem: {
        item: 0
      }
    }
  ];
}

return rows.map((row) => ({
  json: {
    ...row,
    has_pick_rows: true
  },
  pairedItem: {
    item: 0
  }
}));

const source = $input.first().json;

const rows = Array.isArray(source.prop_rows)
  ? source.prop_rows
  : [];

// Always return at least one item.
// Otherwise a video with zero props silently ends this branch.
if (rows.length === 0) {
  return [
    {
      json: {
        has_prop_rows: false,
        video_id: source.video_id,
        event_key: source.event_key,
        spreadsheet_id: source.spreadsheet_id,
        prop_row_count: 0
      },
      pairedItem: {
        item: 0
      }
    }
  ];
}

return rows.map((row) => ({
  json: {
    ...row,
    has_prop_rows: true
  },
  pairedItem: {
    item: 0
  }
}));

const source = $json;
const row = source.extraction_log_row;

if (!row || typeof row !== 'object') {
  throw new Error(
    `Missing extraction_log_row for video ${source.video_id || 'unknown'}`
  );
}

return {
  json: row
};

const source = $('Prepare Extraction Rows').first().json;
const expectedRows = Number(source.pick_row_count || 0);
const inputItems = $input.all();

if (expectedRows === 0) {
  return [
    {
      json: {
        video_id: source.video_id,
        branch: 'picks',
        status: 'SKIPPED',
        expected_rows: 0,
        processed_items: 0
      }
    }
  ];
}

const processedItems = inputItems.length;

if (processedItems !== expectedRows) {
  throw new Error(
    `Pick write count mismatch: expected ${expectedRows}, ` +
    `processed ${processedItems}`
  );
}

return [
  {
    json: {
      video_id: source.video_id,
      branch: 'picks',
      status: 'COMPLETED',
      expected_rows: expectedRows,
      processed_items: processedItems
    }
  }
];

const source = $('Prepare Extraction Rows').first().json;
const expectedRows = Number(source.prop_row_count || 0);
const inputItems = $input.all();

if (expectedRows === 0) {
  return [
    {
      json: {
        video_id: source.video_id,
        branch: 'props',
        status: 'SKIPPED',
        expected_rows: 0,
        processed_items: 0
      }
    }
  ];
}

const processedItems = inputItems.length;

if (processedItems !== expectedRows) {
  throw new Error(
    `Prop write count mismatch: expected ${expectedRows}, ` +
    `processed ${processedItems}`
  );
}

return [
  {
    json: {
      video_id: source.video_id,
      branch: 'props',
      status: 'COMPLETED',
      expected_rows: expectedRows,
      processed_items: processedItems
    }
  }
];

const source = $('Prepare Extraction Rows').first().json;
const processedItems = $input.all().length;

if (processedItems !== 1) {
  throw new Error(
    `Extraction Log write count mismatch: expected 1, ` +
    `processed ${processedItems}`
  );
}

return [
  {
    json: {
      video_id: source.video_id,
      branch: 'extraction_log',
      status: 'COMPLETED',
      expected_rows: 1,
      processed_items: processedItems,
    },
  },
];

const items = $input.all();

const source =
  $('Prepare Extraction Rows').first().json;

const expectedBranches = [
  'picks',
  'props',
  'extraction_log',
];

const received =
  items.map((item) => ({
    branch:
      String(item.json?.branch || ''),

    status:
      String(item.json?.status || ''),

    expected_rows:
      Number(item.json?.expected_rows || 0),

    processed_items:
      Number(item.json?.processed_items || 0),
  }));

const errors = [];

for (
  const expectedBranch
  of expectedBranches
) {
  const matches =
    received.filter(
      (result) =>
        result.branch === expectedBranch
    );

  if (matches.length === 0) {
    errors.push(
      `Missing completion signal for branch: ${expectedBranch}`
    );

    continue;
  }

  if (matches.length > 1) {
    errors.push(
      `Duplicate completion signals for branch: ${expectedBranch}`
    );

    continue;
  }

  const result =
    matches[0];

  if (
    ![
      'COMPLETED',
      'SKIPPED',
    ].includes(result.status)
  ) {
    errors.push(
      `Invalid status for ${expectedBranch}: ${result.status || 'missing'}`
    );
  }

  if (
    result.status === 'COMPLETED' &&
    result.processed_items !==
      result.expected_rows
  ) {
    errors.push(
      `${expectedBranch} count mismatch: expected ` +
      `${result.expected_rows}, processed ` +
      `${result.processed_items}`
    );
  }

  if (
    result.status === 'SKIPPED' &&
    result.expected_rows !== 0
  ) {
    errors.push(
      `${expectedBranch} was skipped despite expecting ` +
      `${result.expected_rows} rows`
    );
  }
}

if (items.length !== 3) {
  errors.push(
    `Expected 3 branch completion items, received ${items.length}`
  );
}

if (errors.length > 0) {
  throw new Error(
    `Spreadsheet write verification failed: ${errors.join(' | ')}`
  );
}

return [
  {
    json: {
      video_id:
        source.video_id,

      event_key:
        source.event_key,

      spreadsheet_id:
        source.spreadsheet_id,

      model_name:
        source.model_name,

      prompt_version:
        source.prompt_version,

      write_status:
        'COMPLETED',

      completed_branch_count:
        3,

      pick_rows_written:
        Number(
          source.pick_row_count || 0
        ),

      prop_rows_written:
        Number(
          source.prop_row_count || 0
        ),

      branch_results:
        received,
    },
  },
];

const prepared =
  $('Prepare Extraction Rows').first().json;

const validated =
  $('Validate and Sort Extraction').first().json;

const picks = Array.isArray(prepared.pick_rows)
  ? prepared.pick_rows
  : [];

const props = Array.isArray(prepared.prop_rows)
  ? prepared.prop_rows
  : [];

const videoId =
  prepared.video_id ||
  validated.video_id ||
  '';

const channelName =
  prepared.channel_name ||
  validated.channel_name ||
  'Unknown picker';

const videoTitle =
  prepared.video_title ||
  validated.video_title ||
  '';

const eventName =
  prepared.event_name ||
  validated.event_name ||
  prepared.event_key ||
  validated.event_key ||
  '';

const eventKey =
  prepared.event_key ||
  validated.event_key ||
  '';

const spreadsheetId =
  prepared.spreadsheet_id ||
  validated.spreadsheet_id ||
  '';

const spreadsheetUrl =
  prepared.spreadsheet_url ||
