/*
Telegram HTML escaping.
*/
function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/*
Keep reasoning short enough for Telegram.
*/
function conciseReason(
  value,
  maxLength = 190
) {
  const text = String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();

  if (!text) {
    return '';
  }

  const sentenceMatch =
    text.match(/^.*?[.!?](?:\s|$)/);

  const firstSentence =
    sentenceMatch
      ? sentenceMatch[0].trim()
      : text;

  if (
    firstSentence.length <= maxLength
  ) {
    return firstSentence;
  }

  return (
    `${firstSentence
      .slice(0, maxLength - 1)
      .trim()}…`
  );
}

/*
Describe predicted method of victory.
*/
function describeWinningMethod(prop) {
  if (!prop) {
    return 'to win';
  }

  const roundText =
    prop.round
      ? ` in R${prop.round}`
      : prop.round_range
        ? ` in ${prop.round_range}`
        : '';

  switch (prop.market) {
    case 'method_and_round':
    case 'method_of_victory': {
      if (
        prop.method === 'KO_TKO'
      ) {
        return `by KO/TKO${roundText}`;
      }

      if (
        prop.method === 'submission'
      ) {
        return `by submission${roundText}`;
      }

      if (
        prop.method === 'decision'
      ) {
        return 'by decision';
      }

      return prop.selection
        ? String(prop.selection)
        : 'to win';
    }

    case 'inside_distance':
      return (
        `inside the distance${roundText}`
      );

    case 'winning_round':
      return prop.round
        ? `to win in R${prop.round}`
        : prop.round_range
          ? `to win in ${prop.round_range}`
          : 'to win';

    default:
      return 'to win';
  }
}

/*
Find the most useful method prop for the winner.
*/
function findWinningMethodProp(pick) {
  const matchingProps =
    props.filter((prop) => {
      return (
        Number(prop.fight_order) ===
          Number(pick.fight_order) &&
        prop.fighter ===
          pick.picked_fighter
      );
    });

  const marketPriority = [
    'method_and_round',
    'method_of_victory',
    'inside_distance',
    'winning_round',
  ];

  for (
    const market
    of marketPriority
  ) {
    const match =
      matchingProps.find(
        (prop) =>
          prop.market === market
      );

    if (match) {
      return match;
    }
  }

  return null;
}

